ja=[];unmapped=[]
for i,n in enumerate(nodes):
 text=str(n)
 if n.find_parent('dt',class_='sig'):t=text
 elif i in M:t=M[i]
 elif text in ['Note','Warning','Returns','Example:','.'] :t={'Note':'注記','Warning':'警告','Returns':'戻り値','Example:':'例:','.':'。'}[text]
 elif re.fullmatch(r'New in version [0-9.]+\.',text):t='バージョン'+text.removeprefix('New in version ')[:-1]+'で追加。'
 elif text.startswith('Changed in version '):t='バージョン'+text.removeprefix('Changed in version ').split(':')[0]+'での変更: '
 else:
  t=text
  if re.search(r'\s[a-zA-Z]{2}',text) and not text.startswith(('[flags] handle-type handle-address','RtlGenRandom <','getrandom(2) <','getentropy(2) <','sysctl(7) <')):unmapped.append((i,text))
 assert '\n' not in t or t==text
 ja.append(t.replace('\n',' ') if not n.find_parent('dt',class_='sig') else t)
assert not unmapped,unmapped
assert len(ja)==1540
(ev/'ja-nodes.txt').write_text('\n'.join(ja)+'\n');print('1540 mapped nodes saved')
